SELECT CASE WHEN duration_sec >= 477 THEN 'high' WHEN duration_sec >= 120 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, SUM(CASE WHEN page = '/product' THEN 1 ELSE 0 END) AS product_count, MIN(event_time) AS min_event_time, AVG(duration_sec) AS avg_duration_sec FROM web_events WHERE event_time < '2025-10-18' GROUP BY CASE WHEN duration_sec >= 477 THEN 'high' WHEN duration_sec >= 120 THEN 'mid' ELSE 'low' END ORDER BY duration_sec_bucket ASC;
